import {
  buildData,
  encodeCanonicalJson,
  encodePrettyPrintedJson,
  iterencodeCanonicalJson,
  parseArguments,
  toPythonBytesRepr,
} from './lib/index.mjs';

export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  const parsed = parseArguments(argv, scriptPath);

  if (parsed.status === 'help') {
    process.stdout.write(parsed.text);
    return 0;
  }

  if (parsed.status === 'error') {
    process.stderr.write(parsed.text);
    return parsed.code;
  }

  const data = buildData(parsed.values);
  const canonicalResult = encodeCanonicalJson(data);
  const prettyResult = encodePrettyPrintedJson(data);
  const canonicalChunks = Array.from(iterencodeCanonicalJson(data));

  console.log(toPythonBytesRepr(canonicalResult));
  console.log(toPythonBytesRepr(prettyResult));
  console.log(canonicalChunks.length);
  return 0;
}

const currentPath = decodeURIComponent(new URL(import.meta.url).pathname);

if (process.argv[1] === currentPath) {
  const exitCode = main();
  if (exitCode !== 0) {
    process.exitCode = exitCode;
  }
}

