  if (value === 0) {
    return '0.0';
  }

  const sign = value < 0 ? '-' : '';
  const absolute = Math.abs(value);
  const [coefficient, exponentText] = absolute.toExponential().split('e');
  const exponent = Number(exponentText);

  if (exponent < -4 || exponent >= 16) {
    return `${sign}${coefficient}e${formatExponent(exponent)}`;
  }

  const fixed = scientificToFixed(coefficient, exponent);
  return fixed.includes('.') ? `${sign}${fixed}` : `${sign}${fixed}.0`;
}

