export function toPythonBytesRepr(value) {
  const bytes = Buffer.isBuffer(value) ? value : Buffer.from(value, 'utf8');
  let output = "b'";

  for (const byte of bytes) {
    if (byte === 0x09) {
      output += '\\t';
      continue;
    }

    if (byte === 0x0a) {
      output += '\\n';
      continue;
    }

    if (byte === 0x0d) {
      output += '\\r';
      continue;
    }

    if (byte === 0x5c) {
      output += '\\\\';
      continue;
    }

    if (byte === 0x27) {
      output += "\\'";
      continue;
    }

    if (byte >= 0x20 && byte <= 0x7e) {
      output += String.fromCharCode(byte);
      continue;
    }

    output += `\\x${byte.toString(16).padStart(2, '0')}`;
  }

  output += "'";
  return output;
}

