import {
  isArgparseLikeNegativeFloatToken,
  isArgparseLikeNegativeIntToken,
  parseFloatArgument,
  parseIntegerArgument,
} from './number_format.mjs';

const OPTION_SPECS = {
  '--a': { name: 'a', metavar: 'A', type: 'string' },
  '--b': { name: 'b', metavar: 'B', type: 'int' },
  '--c': { name: 'c', metavar: 'C', type: 'float' },
};

const REQUIRED_OPTIONS = ['--a', '--b', '--c'];

function basename(pathValue) {
  if (!pathValue) {
    return 'test10.mjs';
  }

  const normalized = pathValue.replaceAll('\\', '/');
  const segments = normalized.split('/');
  return segments[segments.length - 1] || 'test10.mjs';
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C\n`;
}

function helpText(programName) {
  return `${usage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

function errorText(programName, message) {
  return `${usage(programName)}${programName}: error: ${message}\n`;
}

function isHelpOption(token) {
  return token === '-h' || (token.startsWith('--') && !token.includes('=') && '--help'.startsWith(token));
}

function isHelpOptionWithExplicitArgument(token) {
  if (!token.startsWith('--') || !token.includes('=')) {
    return false;
  }

  const [optionName] = token.split('=', 1);
  return '--help'.startsWith(optionName);
}

function shouldTreatAsMissingValue(nextToken, optionType) {
  if (!nextToken.startsWith('-')) {
    return false;
  }

  if (optionType === 'string') {
    return true;
  }

  if (optionType === 'int') {
    return !isArgparseLikeNegativeIntToken(nextToken);
  }

  if (optionType === 'float') {
    return !isArgparseLikeNegativeFloatToken(nextToken);
  }

  return true;
}

function parseValue(spec, rawValue) {
  if (spec.type === 'string') {
    return rawValue;
  }

  if (spec.type === 'int') {
    return parseIntegerArgument(rawValue);
  }

  return parseFloatArgument(rawValue);
}

export function parseArguments(argv, scriptPath) {
  const programName = basename(scriptPath);
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (isHelpOptionWithExplicitArgument(token)) {
      const explicitArgument = token.slice(token.indexOf('=') + 1);
      return {
        code: 2,
        status: 'error',
        text: errorText(programName, `argument -h/--help: ignored explicit argument '${explicitArgument}'`),
      };
    }

    if (isHelpOption(token)) {
      return {
        code: 0,
        status: 'help',
        text: helpText(programName),
      };
    }

    const equalsIndex = token.indexOf('=');
    const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
    const spec = OPTION_SPECS[optionName];

    if (!spec) {
      extras.push(token);
      continue;
    }

    let rawValue;
    if (equalsIndex !== -1) {
      rawValue = token.slice(equalsIndex + 1);
    } else {
      const nextToken = argv[index + 1];
      if (nextToken === undefined || shouldTreatAsMissingValue(nextToken, spec.type)) {
        return {
          code: 2,
          status: 'error',
          text: errorText(programName, `argument ${optionName}: expected one argument`),
        };
      }

      rawValue = nextToken;
      index += 1;
    }

    try {
      values[spec.name] = parseValue(spec, rawValue);
    } catch (error) {
      return {
        code: 2,
        status: 'error',
        text: errorText(programName, `argument ${optionName}: ${error.message}`),
      };
    }
  }

  const missing = REQUIRED_OPTIONS.filter((optionName) => {
    const spec = OPTION_SPECS[optionName];
    return !(spec.name in values);
  });

  if (missing.length > 0) {
    return {
      code: 2,
      status: 'error',
      text: errorText(programName, `the following arguments are required: ${missing.join(', ')}`),
    };
  }

  if (extras.length > 0) {
    return {
      code: 2,
      status: 'error',
      text: errorText(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    code: 0,
    status: 'ok',
    values,
  };
}

