import { encodeJsonString, encodePrimitive } from './json_text.mjs';

function compareKeys(left, right) {
  if (left < right) {
    return -1;
  }

  if (left > right) {
    return 1;
  }

  return 0;
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function sortedKeys(value) {
  return Object.keys(value).sort(compareKeys);
}

function serializePretty(value, indentLevel = 0) {
  if (Array.isArray(value)) {
    if (value.length === 0) {
      return '[]';
    }

    const indent = ' '.repeat((indentLevel + 1) * 4);
    const closingIndent = ' '.repeat(indentLevel * 4);
    const body = value
      .map((item) => `${indent}${serializePretty(item, indentLevel + 1)}`)
      .join(',\n');
    return `[\n${body}\n${closingIndent}]`;
  }

  if (isPlainObject(value)) {
    const keys = sortedKeys(value);
    if (keys.length === 0) {
      return '{}';
    }

    const indent = ' '.repeat((indentLevel + 1) * 4);
    const closingIndent = ' '.repeat(indentLevel * 4);
    const body = keys
      .map((key) => `${indent}${encodeJsonString(key)}: ${serializePretty(value[key], indentLevel + 1)}`)
      .join(',\n');
    return `{\n${body}\n${closingIndent}}`;
  }

  return encodePrimitive(value);
}

function* iterencodeCanonicalValue(value) {
  if (Array.isArray(value)) {
    if (value.length === 0) {
      yield '[]';
      return;
    }

    for (let index = 0; index < value.length; index += 1) {
      const nestedChunks = Array.from(iterencodeCanonicalValue(value[index]));
      nestedChunks[0] = `${index === 0 ? '[' : ','}${nestedChunks[0]}`;
      yield* nestedChunks;
    }

    yield ']';
    return;
  }

  if (isPlainObject(value)) {
    const keys = sortedKeys(value);
    if (keys.length === 0) {
      yield '{}';
      return;
    }

    yield '{';

    for (let index = 0; index < keys.length; index += 1) {
      const key = keys[index];
      if (index !== 0) {
        yield ',';
      }
      yield encodeJsonString(key);
      yield ':';
      yield* iterencodeCanonicalValue(value[key]);
    }

    yield '}';
    return;
  }

  yield encodePrimitive(value);
}

export function encodeCanonicalJson(value) {
  return Buffer.from(Array.from(iterencodeCanonicalValue(value)).join(''), 'utf8');
}

export function encodePrettyPrintedJson(value) {
  return Buffer.from(serializePretty(value), 'utf8');
}

export function* iterencodeCanonicalJson(value) {
  for (const chunk of iterencodeCanonicalValue(value)) {
    yield Buffer.from(chunk, 'utf8');
  }
}

export {
  encodeCanonicalJson as encode_canonical_json,
  encodePrettyPrintedJson as encode_pretty_printed_json,
  iterencodeCanonicalJson as iterencode_canonical_json,
};

